// Generated from the source game's game.db (affix_template): every affix. Stats are "id:multiplier" pairs with the source game's
// stat ids (from the client executable): 1 Mana, 2 Health, 3 Armor, 4 Strength, 5 Agility, 6 Willpower, 7 Intelligence,
// 8 Courage, 9 Regeneration, 10 Meditate, 11 Weapon Value, 13 Ranged Weapon Value, 15-17 Melee/Ranged/Spell
// Critical, 18 Dodge, 19 Block, 21-24 Resist Frost/Fire/Shadow/Holy, 28-35 Staves, Maces, Axes, Swords, Ranged,
// Daggers, Wands, Shields.
namespace RPG.EditorTools
{
    internal static class AffixData
    {
        public const int Mana = 1, Health = 2, Armor = 3, WeaponValue = 11, RangedWeaponValue = 13;

        /// <summary>The attribute of a source-game stat id, or null for the ones that are not attributes here (mana, health, armor, weapon value).</summary>
        public static RPG.Progression.Attribute? AttributeOf(int stat)
        {
            switch (stat)
            {
                case 4: return RPG.Progression.Attribute.Strength;
                case 5: return RPG.Progression.Attribute.Agility;
                case 6: return RPG.Progression.Attribute.Willpower;
                case 7: return RPG.Progression.Attribute.Intelligence;
                case 8: return RPG.Progression.Attribute.Vitality;
                case 9: return RPG.Progression.Attribute.Regeneration;
                case 10: return RPG.Progression.Attribute.Meditate;
                case 15: return RPG.Progression.Attribute.MeleeCritical;
                case 16: return RPG.Progression.Attribute.RangedCritical;
                case 17: return RPG.Progression.Attribute.SpellCritical;
                case 18: return RPG.Progression.Attribute.Dodge;
                case 19: return RPG.Progression.Attribute.Block;
                case 21: return RPG.Progression.Attribute.ResistFrost;
                case 22: return RPG.Progression.Attribute.ResistFire;
                case 23: return RPG.Progression.Attribute.ResistShadow;
                case 24: return RPG.Progression.Attribute.ResistHoly;
                case 28: return RPG.Progression.Attribute.Staves;
                case 29: return RPG.Progression.Attribute.Maces;
                case 30: return RPG.Progression.Attribute.Axes;
                case 31: return RPG.Progression.Attribute.Swords;
                case 32: return RPG.Progression.Attribute.Ranged;
                case 33: return RPG.Progression.Attribute.Daggers;
                case 34: return RPG.Progression.Attribute.Wands;
                case 35: return RPG.Progression.Attribute.Shields;
                default: return null;
            }
        }

